[Q]: Write a JavaScript function that takes an array as input and returns the second largest element in the array.
[A]: Function findSecondLargest(arr) {
   let largest = arr[0];
   let secondLargest = -Infinity;
   for (let i = 1; i < arr.length; i++) {
      if (arr[i] > largest) {
         secondLargest = largest;
         largest = arr[i];
      } else if (arr[i] > secondLargest && arr[i] !== largest) {
         secondLargest = arr[i];
      }
   }
   return secondLargest;
}

// Example usage:
console.log(findSecondLargest([5, 2, 8, 1, 6])); // Output: 5 (second largest element is 8)
console.log(findSecondLargest([-10, 3, 7, 2, -5])); // Output: 7 (second largest element is 3)

Sure! Here's a JavaScript function that will switch the order of adjectives in a sentence:

```javascript
function swapAdjectives(sentence) {
  // Split the string into an array of words
  const words = sentence.split(" ");

  // Filter out common stop words like "the", "a", and "an"
  const filteredWords = words.filter((word) => !["the", "a", "an"].includes(word));

  // Find the indices of the first two adjectives (excluding common stop words)
  const [firstAdjIndex, secondAdjIndex] = filteredWords.reduce((acc, curr, i) => {
    const isAdj = /^[a-zA-Z]+$/.test(curr);
    const isStopWord = ["the", "a", "an"].includes(curr);

    // If we find two adjectives, save their indices and return early
    if (acc[1] !== undefined && !isStopWord) {
      return [i - 1, i];
    }

    // Otherwise, keep looking for the next pair of adjectives
    if (!isStopWord && isAdj) {
      acc[0] = i;
    }

    // Return the accumulator (which contains the last known index)
    return acc;
  }, [-1, -1]);

  // Swap the positions of the first two adjectives
  const swappedWords = [...words.slice(0, firstAdjIndex), words[secondAdjIndex], words[firstAdjIndex], ...words.slice(firstAdjIndex + 1, secondAdjIndex), ...words.slice(secondAdjIndex + 1)];

  // Join the swapped words back into a sentence
  const result = swappedWords.join(" ");

  // Return the modified sentence
  return result;
}
```

