response:
Here's an implementation of the bubble sort algorithm in C++ to sort an integer array in ascending order:

```cpp
#include <iostream>
#include <vector>

// Function to implement bubble sort algorithm
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = false; // Flag to check if any swap is made in a pass
    for (int i = 0; i < n - 1; ++i) {
        swapped = false;
        for (int j = 0; j < n - i - 1; ++j) {
            if (arr[j] > arr[j+1]) { // Swap elements if left element is greater than right element
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
                swapped = true;
            }
        }
        // If no swap was made in a pass, array is already sorted
        if (!swapped) break;
    }
}

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    bubbleSort(arr);
    std::cout << "Sorted array: ";
    for (int I : arr) {
        std::cout << I << " ";
    }
    return 0;
}
```

