Here's a JavaScript function that takes a dot-notated string as input and returns all values from an object or array where the nested property matches the given value:

```javascript
function findValuesByProperty(obj, propStr, value) {
  let props = propStr.split("."); // Split the dot-notated string into an array of properties
  let currentObj = obj; // Initialize the current object being processed

  for (let I = 0; I < props.length - 1; i++) { // Loop through each property except the last one
    if (!currentObj[props[i]]) { // If the property doesn't exist, return an empty array
      return [];
    }
    currentObj = currentObj[props[i]]; // Move to the next level of nesting
  }

  let propName = props[props.length - 1]; // Get the name of the final property
  let results = []; // Initialize an empty array to hold the matching values

  if (Array.isArray(currentObj)) { // If the last property is an array...
    for (let I = 0; I < currentObj.length; i++) { // ...loop through it and push matching values to the results array
      if (currentObj[i][propName] === value) {
        results.push(currentObj[i]);
      }
    }
  } else { // If the last property is not an array...
    if (currentObj[propName] === value) { // ...push the entire object to the results array if it matches
      results.push(currentObj);
    }
  }

  return results; // Return the array of matching values
}
```

The function takes three arguments: `obj`, which is the object or array containing the nested properties; `propStr`, which is the dot-notated string representing the path to the nested property; and `value`, which is the value that we want to match against the nested property.

